import{_ as r,o as s,c as l,ag as e,j as c}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"06.3 子网划分与掩码计算 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/03-子网划分.md","filePath":"06-计算机网络/03-子网划分.md"}'),x={name:"06-计算机网络/03-子网划分.md"},h={class:"fig"},a={"data-figure-id":"figure-37",viewBox:"0 0 720 236",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"子网掩码位带图：IP 地址 172.16.50.188、子网掩码 255.255.224.0、两者按位与得到网络地址 172.16.32.0。掩码行的颜色区分三种位段：前两个字节绿底为 B 类默认网络位，第三字节前 3 位金色为借来的子网位，其余灰色为主机位。第三字节中 IP 的 50 与掩码 224 按位与得 32，后 5 位被清零"};function i(o,t,d,g,n,b){return s(),l("div",null,[t[2]||(t[2]=e('<h1 id="_06-3-子网划分与掩码计算-★★★" tabindex="-1">06.3 子网划分与掩码计算 ★★★ <a class="header-anchor" href="#_06-3-子网划分与掩码计算-★★★" aria-label="Permalink to &quot;06.3 子网划分与掩码计算 ★★★&quot;">​</a></h1><h3 id="为什么要划子网" tabindex="-1">为什么要划子网 <a class="header-anchor" href="#为什么要划子网" aria-label="Permalink to &quot;为什么要划子网&quot;">​</a></h3><p>以 B 类地址 172.16.0.0 为例：默认主机位 16 位，理论可容纳 65534 台主机。问题来了——</p><ol><li><strong>浪费</strong>：一个只有 100 人的公司分到这么一段地址，6 万多个地址用不上；按类整段分配太粗放。</li><li><strong>广播风暴</strong>：6 万多台主机在<strong>同一个广播域</strong>里，任何人发一个广播帧全网都得收，性能灾难。</li><li><strong>管理混乱</strong>：公司内部财务、人事、技术混在一个网段，无法隔离。</li></ol><p>解决办法：<strong>从主机位借几位出来当&quot;子网位&quot;</strong>，把一个大网段切成若干个小网段（子网），每个子网是一个独立的广播域。借位后网络位变长，就需要<strong>子网掩码</strong>来标明&quot;32 位里前多少位是网络位&quot;。</p><h3 id="子网掩码的本质" tabindex="-1">子网掩码的本质 <a class="header-anchor" href="#子网掩码的本质" aria-label="Permalink to &quot;子网掩码的本质&quot;">​</a></h3><p>子网掩码也是 32 位：<strong>网络位（含子网位）全写 1，主机位全写 0</strong>。IP 地址与掩码按位&quot;与&quot;（AND）运算，得到<strong>网络地址</strong>。掩码有两种等价写法，必须会互转：</p><ul><li>点分十进制：<code>255.255.255.192</code></li><li>CIDR 斜线记法：<code>/26</code>（表示前 26 位是 1）</li></ul><p><strong>掩码速查表（考场上就靠这张表）</strong>——记&quot;借到第几位、掩码字节是多少&quot;：</p><table tabindex="0"><thead><tr><th>主机位数</th><th>/25</th><th>/26</th><th>/27</th><th>/28</th><th>/29</th><th>/30</th></tr></thead><tbody><tr><td>最后一字节掩码</td><td>128</td><td>192</td><td>224</td><td>240</td><td>248</td><td>252</td></tr><tr><td>块大小（步长）</td><td>128</td><td><strong>64</strong></td><td>32</td><td>16</td><td>8</td><td>4</td></tr><tr><td>可用主机数</td><td>126</td><td><strong>62</strong></td><td>30</td><td>14</td><td>6</td><td>2</td></tr></tbody></table><p>若是借第三字节（/17～/23），规律相同：/17→128、/18→192、/19→224、/20→240、/21→248、/22→252、/23→254，只是作用在<strong>第三字节</strong>上。</p><p>&quot;网络位全 1、主机位全 0、按位与&quot;这三句话，落在位带上就是下面这一张图（例：B 类地址 172.16.50.188，默认 /16，向<strong>第三字节</strong>借 3 位成 /19——正是速查表末尾那句话的现场版）：</p>',12)),c("figure",h,[(s(),l("svg",a,[...t[0]||(t[0]=[e('<text class="tt" x="8" y="18">一条地址在位带上的一生：IP × 掩码 按位与 → 网络地址</text><text class="rlab" x="8" y="52">IP 地址</text><text class="rlab" x="8" y="100">子网掩码</text><text class="rlab" x="8" y="148">与的结果</text><rect class="blk bd" x="88" y="38" width="64" height="22"></rect><text class="bt" x="120" y="53">172</text><rect class="blk bd" x="152" y="38" width="64" height="22"></rect><text class="bt" x="184" y="53">16</text><rect class="cell bd" x="240" y="38" width="20" height="22"></rect><text class="bt" x="250" y="53">0</text><rect class="cell bd" x="260" y="38" width="20" height="22"></rect><text class="bt" x="270" y="53">0</text><rect class="cell bd" x="280" y="38" width="20" height="22"></rect><text class="bt" x="290" y="53">1</text><rect class="cell bd" x="300" y="38" width="20" height="22"></rect><text class="bt" x="310" y="53">1</text><rect class="cell bd" x="320" y="38" width="20" height="22"></rect><text class="bt" x="330" y="53">0</text><rect class="cell bd" x="340" y="38" width="20" height="22"></rect><text class="bt" x="350" y="53">0</text><rect class="cell bd" x="360" y="38" width="20" height="22"></rect><text class="bt" x="370" y="53">1</text><rect class="cell bd" x="380" y="38" width="20" height="22"></rect><text class="bt" x="390" y="53">0</text><rect class="cell bd" x="404" y="38" width="20" height="22"></rect><text class="bt" x="414" y="53">1</text><rect class="cell bd" x="424" y="38" width="20" height="22"></rect><text class="bt" x="434" y="53">0</text><rect class="cell bd" x="444" y="38" width="20" height="22"></rect><text class="bt" x="454" y="53">1</text><rect class="cell bd" x="464" y="38" width="20" height="22"></rect><text class="bt" x="474" y="53">1</text><rect class="cell bd" x="484" y="38" width="20" height="22"></rect><text class="bt" x="494" y="53">1</text><rect class="cell bd" x="504" y="38" width="20" height="22"></rect><text class="bt" x="514" y="53">1</text><rect class="cell bd" x="524" y="38" width="20" height="22"></rect><text class="bt" x="534" y="53">0</text><rect class="cell bd" x="544" y="38" width="20" height="22"></rect><text class="bt" x="554" y="53">0</text><text class="dec" x="315" y="76">50</text><text class="dec" x="479" y="76">188</text><rect class="blk bn" x="88" y="86" width="64" height="22"></rect><text class="bt" x="120" y="101">255</text><rect class="blk bn" x="152" y="86" width="64" height="22"></rect><text class="bt" x="184" y="101">255</text><rect class="cell bs" x="240" y="86" width="20" height="22"></rect><text class="bt" x="250" y="101">1</text><rect class="cell bs" x="260" y="86" width="20" height="22"></rect><text class="bt" x="270" y="101">1</text><rect class="cell bs" x="280" y="86" width="20" height="22"></rect><text class="bt" x="290" y="101">1</text><rect class="cell bh" x="300" y="86" width="20" height="22"></rect><text class="bt" x="310" y="101">0</text><rect class="cell bh" x="320" y="86" width="20" height="22"></rect><text class="bt" x="330" y="101">0</text><rect class="cell bh" x="340" y="86" width="20" height="22"></rect><text class="bt" x="350" y="101">0</text><rect class="cell bh" x="360" y="86" width="20" height="22"></rect><text class="bt" x="370" y="101">0</text><rect class="cell bh" x="380" y="86" width="20" height="22"></rect><text class="bt" x="390" y="101">0</text><rect class="cell bh" x="404" y="86" width="20" height="22"></rect><text class="bt" x="414" y="101">0</text><rect class="cell bh" x="424" y="86" width="20" height="22"></rect><text class="bt" x="434" y="101">0</text><rect class="cell bh" x="444" y="86" width="20" height="22"></rect><text class="bt" x="454" y="101">0</text><rect class="cell bh" x="464" y="86" width="20" height="22"></rect><text class="bt" x="474" y="101">0</text><rect class="cell bh" x="484" y="86" width="20" height="22"></rect><text class="bt" x="494" y="101">0</text><rect class="cell bh" x="504" y="86" width="20" height="22"></rect><text class="bt" x="514" y="101">0</text><rect class="cell bh" x="524" y="86" width="20" height="22"></rect><text class="bt" x="534" y="101">0</text><rect class="cell bh" x="544" y="86" width="20" height="22"></rect><text class="bt" x="554" y="101">0</text><text class="dec" x="315" y="124">224</text><text class="dec" x="479" y="124">0</text><rect class="blk bd" x="88" y="134" width="64" height="22"></rect><text class="bt" x="120" y="149">172</text><rect class="blk bd" x="152" y="134" width="64" height="22"></rect><text class="bt" x="184" y="149">16</text><rect class="cell bn" x="240" y="134" width="20" height="22"></rect><text class="bt" x="250" y="149">0</text><rect class="cell bn" x="260" y="134" width="20" height="22"></rect><text class="bt" x="270" y="149">0</text><rect class="cell bn" x="280" y="134" width="20" height="22"></rect><text class="bt" x="290" y="149">1</text><rect class="cell bh" x="300" y="134" width="20" height="22"></rect><text class="bt" x="310" y="149">0</text><rect class="cell bh" x="320" y="134" width="20" height="22"></rect><text class="bt" x="330" y="149">0</text><rect class="cell bh" x="340" y="134" width="20" height="22"></rect><text class="bt" x="350" y="149">0</text><rect class="cell bh" x="360" y="134" width="20" height="22"></rect><text class="bt" x="370" y="149">0</text><rect class="cell bh" x="380" y="134" width="20" height="22"></rect><text class="bt" x="390" y="149">0</text><rect class="cell bh" x="404" y="134" width="20" height="22"></rect><text class="bt" x="414" y="149">0</text><rect class="cell bh" x="424" y="134" width="20" height="22"></rect><text class="bt" x="434" y="149">0</text><rect class="cell bh" x="444" y="134" width="20" height="22"></rect><text class="bt" x="454" y="149">0</text><rect class="cell bh" x="464" y="134" width="20" height="22"></rect><text class="bt" x="474" y="149">0</text><rect class="cell bh" x="484" y="134" width="20" height="22"></rect><text class="bt" x="494" y="149">0</text><rect class="cell bh" x="504" y="134" width="20" height="22"></rect><text class="bt" x="514" y="149">0</text><rect class="cell bh" x="524" y="134" width="20" height="22"></rect><text class="bt" x="534" y="149">0</text><rect class="cell bh" x="544" y="134" width="20" height="22"></rect><text class="bt" x="554" y="149">0</text><text class="dec" x="315" y="172">32</text><text class="dec" x="479" y="172">0</text><path class="bnd" d="M300 30 V162"></path><text class="anno" x="300" y="26" text-anchor="middle">前 19 位 = 1</text><text class="anno" x="430" y="26">第三字节 50∧224=32：后 5 位被清零</text><text class="rlab" x="8" y="200">■ 绿（前 16 位）= B 类默认网络位　■ 金（第三字节前 3 位）= 借来的子网位　■ 灰（13 位）= 主机位，2¹³−2 = 8190 台可用</text><text class="rlab" x="8" y="222">块大小 32 → 第三字节边界 0、32、64、96…；50 落在 32 块 ✓ 与图中网络地址 172.16.32.0 互相印证。</text>',123)])])),t[1]||(t[1]=c("figcaption",null,'借位只是把"1/0 边界"往左挪几位：挪在第四字节就是 /25～/30（速查表主表），挪进第三字节就是 /17～/23——五步法一字不改，只有"块作用在第几字节"不同。',-1))]),t[3]||(t[3]=e('<h3 id="公式三件套-每个公式的通用形式-算例-口诀" tabindex="-1">公式三件套（每个公式的通用形式 + 算例 + 口诀） <a class="header-anchor" href="#公式三件套-每个公式的通用形式-算例-口诀" aria-label="Permalink to &quot;公式三件套（每个公式的通用形式 + 算例 + 口诀）&quot;">​</a></h3><p><strong>公式 1：可用主机数 = 2^主机位数 − 2</strong></p><ul><li>通用形式：主机位有 m 位 → 2^m − 2。</li><li>代入算例：/26 → 主机位 32−26=6 → 2^6 − 2 = 64 − 2 = <strong>62</strong>。逐项展开：2^6 = 64，减去 1 个网络地址（主机位全 0）和 1 个广播地址（主机位全 1）。</li><li>口诀：<strong>&quot;减 2，扣掉网络和广播&quot;</strong>。</li></ul><p><strong>公式 2：子网个数 = 2^借位数</strong></p><ul><li>通用形式：从主机位借 s 位 → 2^s 个子网。</li><li>代入算例：/24 借 2 位变 /26 → 2^2 = <strong>4</strong> 个子网。</li><li>口诀：<strong>&quot;借几位，翻几番&quot;</strong>。（现代 CIDR 约定下全 0、全 1 子网也可用，软考一律按 2^s 算。）</li></ul><p><strong>公式 3：块大小（步长）= 256 − 掩码最后一个非 255 的字节</strong></p><ul><li>通用形式：块大小即相邻两个子网的网络地址之间的间隔。</li><li>代入算例：掩码 255.255.255.192 → 256 − 192 = <strong>64</strong>。子网边界是 0、64、128、192。</li><li>口诀：<strong>&quot;256 减掩码，得到步长数边界&quot;</strong>。</li></ul><p>三个公式互为印证：块大小 64 = 2^6 = 该网段总地址数；总地址数 − 2 = 可用主机数 62。用&quot;块大小&quot;也能反推主机位数，两条路殊途同归。</p><h3 id="解题步骤模板-五步法-背步骤比背题重要" tabindex="-1">解题步骤模板（五步法，背步骤比背题重要） <a class="header-anchor" href="#解题步骤模板-五步法-背步骤比背题重要" aria-label="Permalink to &quot;解题步骤模板（五步法，背步骤比背题重要）&quot;">​</a></h3><blockquote><p><strong>第 1 步 定位数</strong>：由掩码（或 CIDR 前缀）确定主机位数 m = 32 − 前缀。 <strong>第 2 步 算块大小</strong>：找到掩码最后一个非 255 的字节，块大小 = 256 − 该字节值；确定这个字节所在的是第几字节（第三字节还是第四字节）。 <strong>第 3 步 排边界</strong>：从 0 开始按块大小列出所有子网的起始值，看目标 IP 落在哪个区间 [起点, 起点+块大小−1]。 <strong>第 4 步 写四件套</strong>：网络地址（主机位全 0）、第一个可用地址（网络地址+1）、最后一个可用地址（广播地址−1）、广播地址（下一子网起点−1，即主机位全 1）。 <strong>第 5 步 答可用主机数</strong>：2^m − 2。</p></blockquote><p><strong>例 1（正着算）</strong>：网段 192.168.1.0/26。</p><ul><li>第 1 步：主机位 m = 32 − 26 = 6。</li><li>第 2 步：掩码 255.255.255.<strong>192</strong>，块大小 = 256 − 192 = 64（作用在第四字节）。</li><li>第 3 步：边界 0、64、128、192，共 2^2 = 4 个子网。</li><li>第 4 步：第一个子网 192.168.1.0/26——网络地址 192.168.1.0，可用范围 <strong>192.168.1.1 ～ 192.168.1.62</strong>，广播地址 <strong>192.168.1.63</strong>。</li><li>第 5 步：可用主机数 2^6 − 2 = <strong>62</strong>。</li></ul><p><strong>例 2（反着算：给 IP 求所在子网）</strong>：主机地址 172.16.7.100/27，求它所在子网的网络地址与广播地址。</p><ul><li>方法一（块大小法）：主机位 m = 5，掩码 255.255.255.<strong>224</strong>，块大小 = 256 − 224 = 32。边界：0、32、64、96、128、…。100 落在 [96, 127] → 网络地址 <strong>172.16.7.96</strong>，广播地址 = 96 + 31 = <strong>172.16.7.127</strong>。</li><li>方法二（二进制 AND 验证）：第四字节 100 = <code>01100100</code>，掩码 224 = <code>11100000</code>，按位与得 <code>01100000</code> = <strong>96</strong> ✓ 网络地址 172.16.7.96 一致；主机位剩下 5 位全置 1：<code>01100000</code> → <code>01111111</code> = <strong>127</strong> ✓ 广播地址 172.16.7.127 一致。两种方法结果相同，结论可靠。</li><li>可用主机数 2^5 − 2 = 30，可用范围 172.16.7.97 ～ 172.16.7.126。</li></ul><p><strong>例 3（借位规划题）</strong>：把 C 类网段 192.168.10.0/24 划分成<strong>至少 6 个子网</strong>，且每个子网至少容纳 <strong>25 台主机</strong>，求子网掩码。</p><ul><li>借位数 s：2^s ≥ 6 → s = 3（2^2 = 4 不够，2^3 = 8 ≥ 6）。</li><li>验证主机数：主机位 = 8 − 3 = 5，2^5 − 2 = 30 ≥ 25 ✓（两个条件同时满足）。</li><li>掩码 = /24 + 3 位 = /27 → 255.255.255.<strong>224</strong>。</li><li><strong>必须双向验证</strong>：借 3 位能得到 8 个子网，并且每个子网可用 30 台主机，两个条件均满足。若把主机要求改为“至少 60 台”，借 3 位只能提供 30 台，不满足；借 2 位虽能提供 62 台，却只有 4 个子网，也不满足。因此该 <code>/24</code> 网段无法同时满足“至少 6 个子网、每个至少 60 台”的要求。规划题必须同时验证子网数与主机数。</li></ul><p><strong>反例演示（最易踩的四个坑）</strong>：</p><ol><li><strong>把可用主机数算成 2^m</strong>：/26 有 64 个地址，但<strong>可用主机只有 62</strong>——&quot;减 2&quot;永不能忘。选项里 62 和 64 同时出现时，64 就是给忘了减 2 的人准备的。</li><li><strong>/26 与 /27 混淆</strong>：/26 → 主机位 6 → 62 台；/27 → 主机位 5 → 30 台。考题故意把 255.255.255.192（/26）和 255.255.255.224（/27）放在一起做干扰项，先用&quot;256 减掩码&quot;算块大小再定前缀，不要凭印象。</li><li><strong>广播地址写错成下一子网的网络地址</strong>：块边界 0/64/128/192 时，0 号子网的广播地址是 <strong>63</strong>（=64−1），不是 64——64 是下一个子网的网络地址（主机位全 0，不可用）。</li><li><strong>可用范围两端写反</strong>：可用范围是 [网络地址+1, 广播地址−1]，网络地址和广播地址本身都不在其中。</li></ol><p><strong>应试动作</strong>：① 三个公式背到能默写，掩码速查表（128/192/224/240/248/252 对应 /25～/30）背熟；② 考场一律走五步法：定位数 → 算块大小 → 排边界 → 写四件套 → 算可用数；③ 给 IP 反求子网时，若时间允许用&quot;二进制 AND&quot;快速核一遍网络地址；④ 规划题（给子网数+主机数求掩码）必须把<strong>两个条件都验证</strong>，取能满足两者的最小借位数。</p>',19))])}const w=r(x,[["render",i]]);export{u as __pageData,w as default};
